from . import sl4a
_path=__file__[:-11]

class Android(sl4a.Android):
    _o=sl4a.os
    _l=_o.listdir
    _o=_o.path.isdir
    sl4a._v=locals()

    def _addMethod(_file):
        _l=locals()
        _g=globals()
        _v=sl4a._v
        exec(open(_path+_file+'.py').read(),_g,_l)
        for _i in tuple(_l):
            if _i[0]=='_':
                continue
            _v[_i]=_l[_i]
        _l.clear()

    _f=_path+'fun/'
    for _i in _l(_f):
        _t=open(_f+_i).read()
        exec(_t)

    _f=[_path+'doc/']
    while len(_f)>0:
        _p=_f.pop(-1)
        for _i in _l(_p):
            _t=_p+_i
            if _o(_t):
                _f.append(_t+'/')
            else:
                try:
                    _t=open(_t).read()
                    exec(_i[:-4]+".__doc__=_t")
                except:pass

    _f=_path+'const/'
    for _i in _l(_f):
        try:
            _t=open(_f+_i).read().splitlines()
            _i=_i[:-4]
            _o=[eval(_i+".__doc__"),'']
            if _o[0]==None:
                _o[0]=''
            for _t in _t:
                _p=_i+"."+_t
                exec(_p)
                _o.append(_p)
            _o='\n'.join(_o)
            exec(_i+".__doc__=_o")
        except:pass
    
    def _addMethod(_self,_file):
        from types import MethodType as _mt
        _l=locals()
        _g=globals()
        if '_'+_file in _self.__dict__:
            return
        exec(open(_path+_file+'.py').read(),_g,_l)
        exec(f'_self._{_file}=None')
        for _i in tuple(_l):
            if _i[0]=='_':
                continue
            exec(f'_self.{_i}=_mt({_i},_self)',_g,_l)
        _l.clear()
    
    def _addClass(_self,_file):
        if '_'+_file in _self.__dict__:
            return
        exec(f'_self._{_file}=None')
        exec(f'from .{_file} import {_file}\n{_file}(_self)')
        locals().clear()

    del _f,_i,_t,_l,_o,_p,sl4a._v